 'פליפ עולה כסף, יוצר חובות דיווח בשתי מדינות ודורש בדיקת מס מראש מול רשות המסים. לכן לא כדאי לעשות אותו "ליתר ביטחון". ההסבר המלא במדריך /guides/delaware-flip.',
