 'בודקים אם כדאי להגן על השם כסימן מסחר ברשות הפטנטים. רישום שם חברה לא מגן על המותג.',
 'רושמים ביומן את מועד האגרה השנתית ואת הדוח השנתי לרשם החברות.',
