 'אין לוח זמנים אחד שמתאים לכולם. מוצר תוכנה פשוט אפשר לבדוק מהר, ומוצר עם חומרה, רגולציה או מכירה לארגונים גדולים דורש יותר זמן והון. כדאי לתכנן את התקציב לפי ההנחה הכי יקרה שצריך להוכיח, ולא לפי התרחיש האופטימי. סטארטאפ רפואי, למשל, צריך לתכנן גם את המסלול הרגולטורי, כפי שמוסבר במדריך /guides/eich-lehakim-startup-refui.',
