 'בונים MVP כך: מנסחים את ההנחה החשובה ביותר שצריך לבדוק, בוחרים את הפיצ\'ר האחד שמאפשר לבדוק אותה, ובונים את הגרסה הפשוטה ביותר שמשתמשים אמיתיים יכולים להשתמש בה. לפעמים זה דף נחיתה או אב-טיפוס ולא קוד. מגדירים מראש מה ייחשב הצלחה, משיקים לקבוצה קטנה ולומדים מהשימוש בפועל.',
