 'לפי Y Combinator, SAFE הוא חוזה קצר שבו המשקיע מממן את החברה עכשיו ומקבל זכות למניות בעתיד. ה-SAFE נוצר ב-Y Combinator ב-2013, וגרסת ה-post-money, שבה תקרת השווי מחושבת אחרי ההשקעה, היא הסטנדרט של Y Combinator מאז 2018. יש לו שלוש גרסאות: עם תקרת שווי, עם הנחה, או MFN בלי תקרה ובלי הנחה. ההשוואה המלאה נמצאת במדריך /guides/safe-vs-convertible-note.',
