 'לפי דפי המסלולים, ב-Pre-Seed המענק הוא 60% מגובה הסבב עד 2 מיליון ₪, לחברה שגייסה עד 3 מיליון ₪. ב-Seed המענק הוא 50% מגובה הסבב עד 6 מיליון ₪, לחברה שגייסה עד 15 מיליון ₪. בשני המסלולים צריך מזכר הבנות או הסכם חתום עם משקיע על לפחות 15% מהסבב המבוקש. שאר התנאים מפורטים במדריך /guides/grants-rashut-hachadshanut.',
