 a: 'לוועדה המוסדית אין לוח זמנים ארצי מפורסם, וכל מוסד קובע את סדרי העבודה שלו. כשנדרש גם אישור של משרד הבריאות, היחידה למכשירים מחליטה תוך 30, 45 או 60 ימי עבודה מקבלת בקשה מלאה, לפי מסלול הטיפול.',
