 metaDescription:
 'SAFE או Convertible Note? ההבדלים לפי מסמכי Y Combinator: ריבית, מועד פירעון, Valuation Cap, Discount, MFN, מה קורה כשהחברה נסגרת, ומה לבדוק בחברה ישראלית.',
 speakableAnswer:
 'SAFE הוא הסכם השקעה שבו המשקיע מקבל זכות למניות בסבב הבא. לפי Y Combinator, הוא לא חוב, אין לו ריבית ואין לו מועד פירעון. Convertible Note הוא הלוואה שנצברת עליה ריבית ויש לה מועד פירעון, והיא מומרת למניות בסבב הבא. בפירוק, החוב קודם ל-SAFE.',
