 'לכן, אם החברה רשומה בישראל, צריך עורך דין ישראלי שיתאים את המסמך לדין החברות הישראלי ולתקנון החברה. גם הטיפול במס בצד החברה ובצד המשקיע צריך בדיקה מול יועץ מס בישראל. Y Combinator מציינת שה-SAFE נכתב כדי שיטופל כהון לצורכי מס בארה"ב, וזה לא אומר דבר על הדין הישראלי. חברות שמתכננות לעבור למבנה של חברת אם בדלאוור ימצאו פירוט במדריך /guides/delaware-flip.',
