 'רשות החדשנות נותנת לסטארטאפים ישראליים מענקים מותנים שאינם מדללים. רשות החדשנות לא מקבלת מניות, והחברה מחזירה את המענק רק אם יש לה הכנסות מהפרויקט, דרך תמלוגים מההכנסות. המסלולים העיקריים לחברות צעירות הם תנופה ליזמים בתחילת הדרך, חממות טכנולוגיות, וקרן ההזנק עם מסלולי Pre-Seed, Seed ו-Round A.',
