 faqs: [
 {
 q: 'מה זה Delaware Flip?',
 a: 'Delaware Flip הוא שינוי מבנה שבו בעלי המניות של חברה ישראלית מעבירים את כל מניותיהם לחברה חדשה בדלאוור, ומקבלים במקומן מניות בחברה החדשה באותם יחסים. בסוף התהליך החברה בדלאוור היא חברת האם, והחברה הישראלית היא חברה בת שבה נשארים בדרך כלל הפעילות, העובדים והקניין הרוחני.',
 },
 {
 q: 'האם פליפ מחויב במס בישראל?',
 a: 'העברת מניות לחברה זרה היא ככלל אירוע מס. סעיפים 104א ו-104ב לפקודת מס הכנסה מאפשרים שההעברה לא תחויב במס במועדה, אם מתקיימים התנאים ומתקבל אישור מראש של מנהל רשות המסים. המס נדחה ולא מבוטל, והמניות מופקדות בידי נאמן שאחראי לתשלום המס בעתיד.',
 },
 {
 q: 'מה זה המסלול הירוק של רשות המסים בפליפ?',
 a: 'המסלול הירוק הוא הליך מזורז לקבלת החלטת מיסוי על סמך הצהרות המבקשים. לפליפ יש בו שני טפסים: 982 לפי סעיף 104ב(א) ו-982א לפי סעיף 104א(א). הם מיועדים לחברה שהתאגדה בשנתיים שלפני שנת המס של הבקשה, אלא אם המנהל מאשר אחרת. ההגשה המקוונת פתוחה למייצגים בלבד.',
 },
 {
 q: 'כמה עולה להחזיק חברה בדלאוור בכל שנה?',
 a: 'לפי חטיבת התאגידים של דלאוור, תאגיד מגיש דוח שנתי ומשלם מס זיכיון עד 1 במרץ. אגרת הדוח היא 50 דולר, והמס המינימלי הוא 175 או 400 דולר, לפי שיטת החישוב. איחור עולה 200 דולר קנס וריבית של 1.5% לחודש. בנוסף יש Registered Agent ושכר רואי חשבון.',
 },
 {
 q: 'מה קורה לאופציות של העובדים אחרי פליפ?',
 a: 'בבקשה להחלטת המיסוי מבקשים רצף מס לבעלי אופציות לפי סעיף 102 וסעיף 3(ט). כך האופציות בחברה הישראלית מוחלפות באופציות בחברה בדלאוור באותם תנאים, וההחלפה עצמה לא נחשבת אירוע מס לעובדים. את תוכנית האופציות מכינים לשינוי עוד לפני ההגשה, יחד עם הנאמן של תוכנית 102.',
 },
 {
 q: 'מתי לא כדאי לעשות פליפ?',
 a: 'כשאין משקיע שמבקש מבנה אמריקאי ואין צורך עסקי ברור. פליפ יוצר עלויות ודיווחים קבועים בשתי מדינות, תנאים בהחלטת המיסוי שחלים גם אחר כך, ועבודה משפטית וחשבונאית. הרבה חברות ישראליות מגייסות כחברה ישראלית ועושות פליפ רק כשהצורך מופיע, למשל בבקשה של משקיע מוביל.',
 }],
