 'לכן ההחלטה המרכזית לפני PMF היא במה להתמקד: ללמוד מהלקוחות ולשפר את המוצר, ולא להרחיב את הצוות או את קהל היעד. משקיעים בודקים את הסימנים האלה, כפי שמוסבר במדריך /guides/eich-mgayisim-mashkim.',
