 'תמחור SaaS חשוב כי הוא קובע לא רק כמה כסף נכנס, אלא גם אילו לקוחות תקבלו, איך תמכרו להם ואיך העסק יגדל.',
 'מחיר נמוך עם הרשמה עצמית מוביל למודל של לקוחות קטנים רבים ושיווק דיגיטלי. מחיר גבוה עם חוזים שנתיים מוביל לאנשי מכירות ולמחזורי מכירה ארוכים. לכן כדאי לחשוב על התמחור כבר כשמגדירים את קהל היעד, ולא רק לפני ההשקה. שינוי מודל אחרי שיש בסיס לקוחות אפשרי, אבל מסובך.',
