 'בוחרים את יחידת התמחור לפי מה שמייצר ערך ללקוח וגדל יחד איתו. אם הערך גדל עם מספר העובדים שמשתמשים במוצר, תמחור לפי משתמש הגיוני. אם הוא גדל עם כמות העסקאות או הנתונים, תמחור לפי שימוש מתאים יותר.',
 'יחידת תמחור טובה עומדת בשלושה מבחנים: הלקוח מבין אותה, הוא יכול לצפות פחות או יותר כמה ישלם, והיא גדלה כשהלקוח מקבל יותר ערך. אם היחידה לא קשורה לערך, למשל תשלום לפי פיצ\'ר שהלקוח כמעט לא משתמש בו, תשמעו על זה במשא ומתן.',
 'שאלו גם מי הלקוח וכיצד הוא קונה. ארגון גדול רוצה לרוב תקציב צפוי וחוזה. עסק קטן רוצה להתחיל מהר, בלי שיחת מכירה. ומוצר שאנשים מצרפים אליו עמיתים יכול ליהנות מגרסה חינמית, בעוד שבמוצר בלי אפקט כזה Freemium עלול להיות בעיקר הוצאה.',
