 faqs: [
 {
 q: 'מה מודל התמחור הטוב ביותר ל-SaaS?',
 a: 'אין מודל אחד נכון. בוחרים את יחידת התמחור לפי מה שמייצר ערך ללקוח וגדל יחד איתו: מספר משתמשים, כמות שימוש או היקף פעילות. מוצר לצוותים מתאים לרוב לתמחור לפי משתמש, תשתית או API מתאימים לתמחור לפי שימוש, והרבה מוצרים משלבים חבילות כדי להתאים לסוגי לקוחות שונים.',
 },
 {
 q: 'איך קובעים מחיר ל-SaaS בשלב מוקדם?',
 a: 'מתחילים מהערך ללקוח: כמה הבעיה עולה לו היום, ומה הוא משלם על הפתרון הנוכחי. משם קובעים מחיר ראשון ובודקים אותו מול לקוחות אמיתיים, בהצעות מחיר ובמכירות. בשלב מוקדם עדיף להתחיל במחיר שאפשר להצדיק בערך, ולא במחיר הנמוך ביותר, כי קשה יותר להעלות מחיר מאשר לתת הנחה.',
 },
 {
 q: 'האם Freemium מתאים לסטארטאפ B2B?',
 a: 'לפעמים. Freemium עובד בעיקר כשהמוצר מתפשט דרך המשתמשים, למשל כשהם מזמינים עמיתים, וכשעלות התפעול של משתמש חינמי נמוכה. במוצר B2B שנמכר להחלטה של מנהל, תקופת ניסיון או פיילוט מוגדר מתאימים לרוב יותר. בכל מקרה, הגרסה החינמית צריכה להיות מוגבלת מספיק כדי שלקוחות פעילים ירצו לשדרג.',
 },
 {
 q: 'מתי להעלות מחירים ב-SaaS?',
 a: 'כשהמוצר משתפר משמעותית, כשרואים שלקוחות סוגרים בקלות בלי להתמקח, או כשהמחיר הנוכחי לא מאפשר לממן מכירות ותמיכה. לפני העלאה החליטו מה קורה ללקוחות הקיימים, למשל שמירה על המחיר הישן לתקופה מוגדרת, והודיעו להם מראש. שינויים תכופים בלי הסבר פוגעים באמון.',
 },
 {
 q: 'האם לבקש כרטיס אשראי בתקופת הניסיון?',
 a: 'זו החלטה בין כמות לאיכות. בקשת כרטיס אשראי מראש מסננת נרשמים פחות רציניים ומקלה על המעבר לתשלום, אבל מקטינה את מספר הנרשמים. ניסיון בלי כרטיס מביא יותר משתמשים, אבל פחות מהם ישלמו. כדאי לבדוק את שתי האפשרויות במוצר שלכם ולמדוד הכנסות בסוף התהליך, לא רק הרשמות.',
 },
 {
 q: 'איך מגיבים למתחרה זול יותר?',
 a: 'בדרך כלל לא בהורדת מחיר. תחרות על מחיר מקשה לממן פיתוח, מכירות ותמיכה. במקום זה חדדו למי המוצר שלכם מתאים יותר ולמה, הדגישו את הערך שהלקוח מקבל, וחזקו את מה שקשה להעתיק, כמו אינטגרציות, שירות וידע בתחום. אם המתחרה באמת מתאים יותר ללקוחות מסוימים, אולי הם לא קהל היעד שלכם.',
 },
 {
 q: 'מה זה ACV ו-NRR?',
 a: 'ACV (Annual Contract Value) הוא הערך השנתי של חוזה עם לקוח, בלי עלויות חד-פעמיות. NRR (Net Revenue Retention) מודד כמה הכנסות נשארו מקבוצת לקוחות קיימת אחרי תקופה, כולל הרחבות, שנמוכים ונטישה. משקיעים ב-SaaS בודקים את שניהם, כי הם מראים כמה כל לקוח שווה והאם לקוחות קיימים גדלים או מצטמצמים.',
 }],
