 'לכן ההחלטה הראשונה במיזם רפואי היא ניסוח השימוש המיועד. היא משפיעה על המסלול הרגולטורי, על הראיות שצריך, על העלות ועל לוח הזמנים. על תוכנה רפואית יש מדריך נפרד, /guides/samd-tochna-kemechshir-refui, ועל אפליקציות טיפוליות במדריך /guides/digital-therapeutics-israel.',
