 'גם מערכת האיכות היא חלק מהרגולציה, לא רק ההגשה. בארה"ב דרישות האיכות בייצור מכשירים (Good Manufacturing Practice) נמצאות ב-21 CFR Part 820. לפי FDA, מ-2 בפברואר 2026 החלק הזה נקרא Quality Management System Regulation (QMSR). מיזם שבונה את התיעוד שלו לפי דרישות האיכות מההתחלה חוסך עבודה כפולה בהמשך.',
 'כל מסלול מוסבר במדריך משלו:',
