 // טכנולוגי" e.g. if it got an IIA R&D grant or tax approval in the 3 prior years. "מסלול תנופה –
 // קרן ההזנק" (next submission 09/11/2026): up to 80% of approved budget, cap 200,000 NIS per 12
 // months, not for salaries/overheads, support for up to one year in total, company conditions
 // (revenue <= 200,000 NIS last calendar year, raised <= 500,000 NIS), no need to quit a job or
 // incorporate, no shares to the state, 3% royalties on sales. "מסלול Pre-Seed – קרן ההזנק":
 // IIA joins a Pre-Seed round with private investors, non-dilutive, MoU with an investor required,
 // once per company (page announces changes from 15.7.26, so amounts are not quoted). "מסלול
 // חממות טכנולוגיות 2020": eight-year franchise, run by VCs and companies, no cash from the
 // founder, no need to incorporate before approval. English "Royalties & Intellectual Property":
 // royalties 3%-5% of annual revenues until full repayment plus annual interest (SOFR); funded R&D
 // done in Israel; transfer of know-how abroad subject to IIA approval and repayment.
 // Removed: Innovation Box rates, "50% dilution" in incubators, grant sizes in dollars, success
 // rates, "registration as a startup" and claims linking section 102 to startup status.
