 alt: 'רשימת מסלולים בדף חטיבת הזנק של רשות החדשנות: מסלול Pre-Seed של קרן ההזנק, מסלול חממות טכנולוגיות 2020, מסלול מהיר להארכת ה-Runway, מסלול מעבדות לחדשנות טכנולוגית ומסלול תנופה, כל אחד עם תיאור "למי מיועד המסלול"',
 width: 1200,
