 'מכירה או העברה של ידע שמומן אל מחוץ לישראל כפופה לאישור הרשות ולתשלום לפי נוסחה. זה חשוב במיוחד אם אתם שוקלים בהמשך מבנה עם חברת אם בחו"ל. ראו /guides/delaware-flip.',
