 // technology companies. European Commission "AI Act" page (digital-strategy.ec.europa.eu, last
 // update 19 October 2026): Regulation (EU) 2024/1689, four risk levels, prohibitions 1-8 effective
 // February 2025, transparency rules from August 2026, high-risk obligations from 2 December 2027.
