 'בבדיקת נאותות של Series A המשקיע בודק שהנתונים שהוצגו נכונים ושאין בעיות משפטיות או טכנולוגיות שמסכנות את ההשקעה. היא מעמיקה יותר מאשר ב-Seed, כי הסכומים גדולים יותר וההחלטה נשענת על נתונים.',
