 'בכל אחת מהדרכים החלוקה בין בעלי המניות שונה. במכירה, סעיפי ה-Liquidation Preference בהסכמי ההשקעה קובעים מי מקבל קודם וכמה. לכן אותו מחיר מכירה יכול להשאיר למייסדים סכומים שונים מאוד, לפי התנאים שנחתמו בסבבים הקודמים. על זה כתבנו במדריך /guides/giyus-series-a.',
