 'שני המנגנונים האלה משנים את הערך האמיתי של ההצעה. מחיר גבוה שרובו מותנה ביעדים או בהישארות שווה פחות ממחיר נמוך יותר במזומן. כשמשווים הצעות, מחשבים כמה מגיע לכל בעל מניות ביום הסגירה, כמה מותנה, ובאילו תנאים. כדאי גם לבדוק מי קובע אם היעדים הושגו, כי אחרי המכירה הרוכשת היא שמנהלת את הפעילות.',
